<script setup>import{reactive,ref}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{useAdminAuth}from'../stores/auth.js';const auth=useAdminAuth(),router=useRouter(),loading=ref(false),form=reactive({username:'admin',password:'123456'});const login=async()=>{loading.value=true;try{const user=await auth.login(form);router.push(user.role==='AUDITOR'?'/audits':'/dashboard')}catch(e){ElMessage.error(e.message)}finally{loading.value=false}};const choose=u=>{form.username=u;form.password='123456'}</script>
